#define main inventory_fixture_main
#include "native_source_inventory.cc"
#undef main
#include <filesystem>
#include <cmath>
#include <map>
#include <google/protobuf/text_format.h>
#include "waymo_open_dataset/protos/motion_metrics.pb.h"
int main(int argc,char**argv){try{if(argc!=4)throw std::runtime_error("args");std::ifstream f(argv[1],std::ios::binary);auto data=read(f,std::filesystem::file_size(argv[1]));waymo::open_dataset::Scenario s;if(!s.ParseFromString(data))throw std::runtime_error("scenario");known(s);std::ifstream pfile(argv[2]);std::string text((std::istreambuf_iterator<char>(pfile)),{});waymo::open_dataset::ScenarioPredictions pred;if(!google::protobuf::TextFormat::ParseFromString(text,&pred)||pred.scenario_id()!=s.scenario_id())throw std::runtime_error("prediction identity");std::map<int,const waymo::open_dataset::Track*> targets;for(auto&t:s.tracks_to_predict()){auto&track=s.tracks(t.track_index());targets.emplace(track.id(),&track);}struct Stats{double ade=0,fde=0;int ade_count=0,fde_count=0;};std::map<int,Stats> expected;std::set<int> seen;for(auto&group:pred.multi_modal_predictions()){if(group.joint_predictions_size()!=1)throw std::runtime_error("K");auto&mode=group.joint_predictions(0);if(mode.confidence()!=1||mode.trajectories_size()!=1)throw std::runtime_error("confidence/group");auto&trajectory=mode.trajectories(0);if(!targets.count(trajectory.object_id())||!seen.insert(trajectory.object_id()).second||trajectory.center_x_size()!=16||trajectory.center_y_size()!=16)throw std::runtime_error("native target support");auto&t=*targets.at(trajectory.object_id());if(!t.states(10).valid())throw std::runtime_error("current mask");auto&stat=expected[t.object_type()];double sum=0;int valid=0;for(int step=0;step<16;step++){auto&gt=t.states(15+5*step);if(!gt.valid())continue;double dx=trajectory.center_x(step)-gt.center_x(),dy=trajectory.center_y(step)-gt.center_y();double distance=std::sqrt(dx*dx+dy*dy);sum+=distance;valid++;if(step==15){stat.fde+=distance;stat.fde_count++;}}if(valid){stat.ade+=sum/valid;stat.ade_count++;}}
if(seen.size()!=targets.size())throw std::runtime_error("missing target");std::ofstream out(argv[3]);out.precision(17);out<<"object_type\tade_count\tfde_count\tade\tfde\n";for(auto&entry:expected){auto&x=entry.second;out<<entry.first<<'\t'<<x.ade_count<<'\t'<<x.fde_count<<'\t'<<(x.ade_count?x.ade/x.ade_count:0)<<'\t'<<(x.fde_count?x.fde/x.fde_count:0)<<'\n';}std::cout<<"REFERENCE "<<s.scenario_id()<<" TARGETS "<<seen.size()<<"\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
